COPY ayahs (id, surah_id, ayah_number, text_ar, text_ar_plain, page) FROM stdin;
4001	38	31	إِذْ عُرِضَ عَلَيْهِ بِالْعَشِيِّ الصَّافِنَاتُ الْجِيَادُ	اذ عرض عليه بالعشي الصافنات الجياد	455
4002	38	32	فَقَالَ إِنِّي أَحْبَبْتُ حُبَّ الْخَيْرِ عَنْ ذِكْرِ رَبِّي حَتَّىٰ تَوَارَتْ بِالْحِجَابِ	فقال اني احببت حب الخير عن ذكر ربي حتي توارت بالحجاب	455
4003	38	33	رُدُّوهَا عَلَيَّ ۖ فَطَفِقَ مَسْحًا بِالسُّوقِ وَالْأَعْنَاقِ	ردوها علي  فطفق مسحا بالسوق والاعناق	455
4004	38	34	وَلَقَدْ فَتَنَّا سُلَيْمَانَ وَأَلْقَيْنَا عَلَىٰ كُرْسِيِّهِ جَسَدًا ثُمَّ أَنَابَ	ولقد فتنا سليمان والقينا علي كرسيه جسدا ثم اناب	455
4005	38	35	قَالَ رَبِّ اغْفِرْ لِي وَهَبْ لِي مُلْكًا لَا يَنْبَغِي لِأَحَدٍ مِنْ بَعْدِي ۖ إِنَّكَ أَنْتَ الْوَهَّابُ	قال رب اغفر لي وهب لي ملكا لا ينبغي لاحد من بعدي  انك انت الوهاب	455
4006	38	36	فَسَخَّرْنَا لَهُ الرِّيحَ تَجْرِي بِأَمْرِهِ رُخَاءً حَيْثُ أَصَابَ	فسخرنا له الريح تجري بامره رخاء حيث اصاب	455
4007	38	37	وَالشَّيَاطِينَ كُلَّ بَنَّاءٍ وَغَوَّاصٍ	والشياطين كل بناء وغواص	455
4008	38	38	وَآخَرِينَ مُقَرَّنِينَ فِي الْأَصْفَادِ	واخرين مقرنين في الاصفاد	455
4009	38	39	هَٰذَا عَطَاؤُنَا فَامْنُنْ أَوْ أَمْسِكْ بِغَيْرِ حِسَابٍ	هذا عطاؤنا فامنن او امسك بغير حساب	455
4010	38	40	وَإِنَّ لَهُ عِنْدَنَا لَزُلْفَىٰ وَحُسْنَ مَآبٍ	وان له عندنا لزلفي وحسن ماب	455
4011	38	41	وَاذْكُرْ عَبْدَنَا أَيُّوبَ إِذْ نَادَىٰ رَبَّهُ أَنِّي مَسَّنِيَ الشَّيْطَانُ بِنُصْبٍ وَعَذَابٍ	واذكر عبدنا ايوب اذ نادي ربه اني مسني الشيطان بنصب وعذاب	455
4012	38	42	ارْكُضْ بِرِجْلِكَ ۖ هَٰذَا مُغْتَسَلٌ بَارِدٌ وَشَرَابٌ	اركض برجلك  هذا مغتسل بارد وشراب	455
4013	38	43	وَوَهَبْنَا لَهُ أَهْلَهُ وَمِثْلَهُمْ مَعَهُمْ رَحْمَةً مِنَّا وَذِكْرَىٰ لِأُولِي الْأَلْبَابِ	ووهبنا له اهله ومثلهم معهم رحمة منا وذكري لاولي الالباب	456
4014	38	44	وَخُذْ بِيَدِكَ ضِغْثًا فَاضْرِبْ بِهِ وَلَا تَحْنَثْ ۗ إِنَّا وَجَدْنَاهُ صَابِرًا ۚ نِعْمَ الْعَبْدُ ۖ إِنَّهُ أَوَّابٌ	وخذ بيدك ضغثا فاضرب به ولا تحنث  انا وجدناه صابرا  نعم العبد  انه اواب	456
4015	38	45	وَاذْكُرْ عِبَادَنَا إِبْرَاهِيمَ وَإِسْحَاقَ وَيَعْقُوبَ أُولِي الْأَيْدِي وَالْأَبْصَارِ	واذكر عبادنا ابراهيم واسحاق ويعقوب اولي الايدي والابصار	456
4016	38	46	إِنَّا أَخْلَصْنَاهُمْ بِخَالِصَةٍ ذِكْرَى الدَّارِ	انا اخلصناهم بخالصة ذكري الدار	456
4017	38	47	وَإِنَّهُمْ عِنْدَنَا لَمِنَ الْمُصْطَفَيْنَ الْأَخْيَارِ	وانهم عندنا لمن المصطفين الاخيار	456
4018	38	48	وَاذْكُرْ إِسْمَاعِيلَ وَالْيَسَعَ وَذَا الْكِفْلِ ۖ وَكُلٌّ مِنَ الْأَخْيَارِ	واذكر اسماعيل واليسع وذا الكفل  وكل من الاخيار	456
4019	38	49	هَٰذَا ذِكْرٌ ۚ وَإِنَّ لِلْمُتَّقِينَ لَحُسْنَ مَآبٍ	هذا ذكر  وان للمتقين لحسن ماب	456
4020	38	50	جَنَّاتِ عَدْنٍ مُفَتَّحَةً لَهُمُ الْأَبْوَابُ	جنات عدن مفتحة لهم الابواب	456
4021	38	51	مُتَّكِئِينَ فِيهَا يَدْعُونَ فِيهَا بِفَاكِهَةٍ كَثِيرَةٍ وَشَرَابٍ	متكئين فيها يدعون فيها بفاكهة كثيرة وشراب	456
4022	38	52	۞ وَعِنْدَهُمْ قَاصِرَاتُ الطَّرْفِ أَتْرَابٌ	۞ وعندهم قاصرات الطرف اتراب	456
4023	38	53	هَٰذَا مَا تُوعَدُونَ لِيَوْمِ الْحِسَابِ	هذا ما توعدون ليوم الحساب	456
4024	38	54	إِنَّ هَٰذَا لَرِزْقُنَا مَا لَهُ مِنْ نَفَادٍ	ان هذا لرزقنا ما له من نفاد	456
4025	38	55	هَٰذَا ۚ وَإِنَّ لِلطَّاغِينَ لَشَرَّ مَآبٍ	هذا  وان للطاغين لشر ماب	456
4026	38	56	جَهَنَّمَ يَصْلَوْنَهَا فَبِئْسَ الْمِهَادُ	جهنم يصلونها فبئس المهاد	456
4027	38	57	هَٰذَا فَلْيَذُوقُوهُ حَمِيمٌ وَغَسَّاقٌ	هذا فليذوقوه حميم وغساق	456
4028	38	58	وَآخَرُ مِنْ شَكْلِهِ أَزْوَاجٌ	واخر من شكله ازواج	456
4029	38	59	هَٰذَا فَوْجٌ مُقْتَحِمٌ مَعَكُمْ ۖ لَا مَرْحَبًا بِهِمْ ۚ إِنَّهُمْ صَالُو النَّارِ	هذا فوج مقتحم معكم  لا مرحبا بهم  انهم صالو النار	456
4030	38	60	قَالُوا بَلْ أَنْتُمْ لَا مَرْحَبًا بِكُمْ ۖ أَنْتُمْ قَدَّمْتُمُوهُ لَنَا ۖ فَبِئْسَ الْقَرَارُ	قالوا بل انتم لا مرحبا بكم  انتم قدمتموه لنا  فبئس القرار	456
4031	38	61	قَالُوا رَبَّنَا مَنْ قَدَّمَ لَنَا هَٰذَا فَزِدْهُ عَذَابًا ضِعْفًا فِي النَّارِ	قالوا ربنا من قدم لنا هذا فزده عذابا ضعفا في النار	456
4032	38	62	وَقَالُوا مَا لَنَا لَا نَرَىٰ رِجَالًا كُنَّا نَعُدُّهُمْ مِنَ الْأَشْرَارِ	وقالوا ما لنا لا نري رجالا كنا نعدهم من الاشرار	457
4033	38	63	أَتَّخَذْنَاهُمْ سِخْرِيًّا أَمْ زَاغَتْ عَنْهُمُ الْأَبْصَارُ	اتخذناهم سخريا ام زاغت عنهم الابصار	457
4034	38	64	إِنَّ ذَٰلِكَ لَحَقٌّ تَخَاصُمُ أَهْلِ النَّارِ	ان ذلك لحق تخاصم اهل النار	457
4035	38	65	قُلْ إِنَّمَا أَنَا مُنْذِرٌ ۖ وَمَا مِنْ إِلَٰهٍ إِلَّا اللَّهُ الْوَاحِدُ الْقَهَّارُ	قل انما انا منذر  وما من اله الا الله الواحد القهار	457
4036	38	66	رَبُّ السَّمَاوَاتِ وَالْأَرْضِ وَمَا بَيْنَهُمَا الْعَزِيزُ الْغَفَّارُ	رب السماوات والارض وما بينهما العزيز الغفار	457
4037	38	67	قُلْ هُوَ نَبَأٌ عَظِيمٌ	قل هو نبا عظيم	457
4038	38	68	أَنْتُمْ عَنْهُ مُعْرِضُونَ	انتم عنه معرضون	457
4039	38	69	مَا كَانَ لِيَ مِنْ عِلْمٍ بِالْمَلَإِ الْأَعْلَىٰ إِذْ يَخْتَصِمُونَ	ما كان لي من علم بالملا الاعلي اذ يختصمون	457
4040	38	70	إِنْ يُوحَىٰ إِلَيَّ إِلَّا أَنَّمَا أَنَا نَذِيرٌ مُبِينٌ	ان يوحي الي الا انما انا نذير مبين	457
4041	38	71	إِذْ قَالَ رَبُّكَ لِلْمَلَائِكَةِ إِنِّي خَالِقٌ بَشَرًا مِنْ طِينٍ	اذ قال ربك للملائكة اني خالق بشرا من طين	457
4042	38	72	فَإِذَا سَوَّيْتُهُ وَنَفَخْتُ فِيهِ مِنْ رُوحِي فَقَعُوا لَهُ سَاجِدِينَ	فاذا سويته ونفخت فيه من روحي فقعوا له ساجدين	457
4043	38	73	فَسَجَدَ الْمَلَائِكَةُ كُلُّهُمْ أَجْمَعُونَ	فسجد الملائكة كلهم اجمعون	457
4044	38	74	إِلَّا إِبْلِيسَ اسْتَكْبَرَ وَكَانَ مِنَ الْكَافِرِينَ	الا ابليس استكبر وكان من الكافرين	457
4045	38	75	قَالَ يَا إِبْلِيسُ مَا مَنَعَكَ أَنْ تَسْجُدَ لِمَا خَلَقْتُ بِيَدَيَّ ۖ أَسْتَكْبَرْتَ أَمْ كُنْتَ مِنَ الْعَالِينَ	قال يا ابليس ما منعك ان تسجد لما خلقت بيدي  استكبرت ام كنت من العالين	457
4046	38	76	قَالَ أَنَا خَيْرٌ مِنْهُ ۖ خَلَقْتَنِي مِنْ نَارٍ وَخَلَقْتَهُ مِنْ طِينٍ	قال انا خير منه  خلقتني من نار وخلقته من طين	457
4047	38	77	قَالَ فَاخْرُجْ مِنْهَا فَإِنَّكَ رَجِيمٌ	قال فاخرج منها فانك رجيم	457
4048	38	78	وَإِنَّ عَلَيْكَ لَعْنَتِي إِلَىٰ يَوْمِ الدِّينِ	وان عليك لعنتي الي يوم الدين	457
4049	38	79	قَالَ رَبِّ فَأَنْظِرْنِي إِلَىٰ يَوْمِ يُبْعَثُونَ	قال رب فانظرني الي يوم يبعثون	457
4050	38	80	قَالَ فَإِنَّكَ مِنَ الْمُنْظَرِينَ	قال فانك من المنظرين	457
4051	38	81	إِلَىٰ يَوْمِ الْوَقْتِ الْمَعْلُومِ	الي يوم الوقت المعلوم	457
4052	38	82	قَالَ فَبِعِزَّتِكَ لَأُغْوِيَنَّهُمْ أَجْمَعِينَ	قال فبعزتك لاغوينهم اجمعين	457
4053	38	83	إِلَّا عِبَادَكَ مِنْهُمُ الْمُخْلَصِينَ	الا عبادك منهم المخلصين	457
4054	38	84	قَالَ فَالْحَقُّ وَالْحَقَّ أَقُولُ	قال فالحق والحق اقول	458
4055	38	85	لَأَمْلَأَنَّ جَهَنَّمَ مِنْكَ وَمِمَّنْ تَبِعَكَ مِنْهُمْ أَجْمَعِينَ	لاملان جهنم منك وممن تبعك منهم اجمعين	458
4056	38	86	قُلْ مَا أَسْأَلُكُمْ عَلَيْهِ مِنْ أَجْرٍ وَمَا أَنَا مِنَ الْمُتَكَلِّفِينَ	قل ما اسالكم عليه من اجر وما انا من المتكلفين	458
4057	38	87	إِنْ هُوَ إِلَّا ذِكْرٌ لِلْعَالَمِينَ	ان هو الا ذكر للعالمين	458
4058	38	88	وَلَتَعْلَمُنَّ نَبَأَهُ بَعْدَ حِينٍ	ولتعلمن نباه بعد حين	458
4059	39	1	بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ تَنْزِيلُ الْكِتَابِ مِنَ اللَّهِ الْعَزِيزِ الْحَكِيمِ	بسم الله الرحمن الرحيم تنزيل الكتاب من الله العزيز الحكيم	458
4060	39	2	إِنَّا أَنْزَلْنَا إِلَيْكَ الْكِتَابَ بِالْحَقِّ فَاعْبُدِ اللَّهَ مُخْلِصًا لَهُ الدِّينَ	انا انزلنا اليك الكتاب بالحق فاعبد الله مخلصا له الدين	458
4061	39	3	أَلَا لِلَّهِ الدِّينُ الْخَالِصُ ۚ وَالَّذِينَ اتَّخَذُوا مِنْ دُونِهِ أَوْلِيَاءَ مَا نَعْبُدُهُمْ إِلَّا لِيُقَرِّبُونَا إِلَى اللَّهِ زُلْفَىٰ إِنَّ اللَّهَ يَحْكُمُ بَيْنَهُمْ فِي مَا هُمْ فِيهِ يَخْتَلِفُونَ ۗ إِنَّ اللَّهَ لَا يَهْدِي مَنْ هُوَ كَاذِبٌ كَفَّارٌ	الا لله الدين الخالص  والذين اتخذوا من دونه اولياء ما نعبدهم الا ليقربونا الي الله زلفي ان الله يحكم بينهم في ما هم فيه يختلفون  ان الله لا يهدي من هو كاذب كفار	458
4062	39	4	لَوْ أَرَادَ اللَّهُ أَنْ يَتَّخِذَ وَلَدًا لَاصْطَفَىٰ مِمَّا يَخْلُقُ مَا يَشَاءُ ۚ سُبْحَانَهُ ۖ هُوَ اللَّهُ الْوَاحِدُ الْقَهَّارُ	لو اراد الله ان يتخذ ولدا لاصطفي مما يخلق ما يشاء  سبحانه  هو الله الواحد القهار	458
